    bool    _is_valid_start_scalar_plain_flow_check_block_token(csubstr s);
    bool    _is_valid_start_scalar_plain_flow_check_qmrk(csubstr s);
    bool    _scan_scalar_plain_handle_newline(csubstr s, size_t offs);
